//! Replays the corpora in `tests/fixtures/`, all generated by running the original Go
//! implementation over the same inputs:
//!
//! * `ip_string.tsv` - `net.IP.String()` over valid, mapped, compressed and malformed bodies;
//! * `messages.tsv` - query info, response validation and answer extraction over raw wire
//!   messages (`parseDNSQuery`, `validateDNSResponseParsed` and the `dns.Msg` walk);
//! * `blocks_trace.tsv` - the dynamic block tracker over a scripted clock.

use std::path::PathBuf;

use diting_dns_core::block::{BlockConfig, DynamicBlocks};
use diting_go_compat::ip::go_ip_string;

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn read(name: &str) -> String {
    let path = fixtures().join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("{} is committed: {error}", path.display()))
}

fn decode_hex(text: &str) -> Vec<u8> {
    assert_eq!(text.len() % 2, 0, "hex length {text:?}");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("hex pair"))
        .collect()
}

#[test]
fn ip_string_matches_go() {
    let text = read("ip_string.tsv");
    let mut rows = 0;
    for (line_number, line) in text.lines().enumerate() {
        if line_number == 0 {
            continue;
        }
        let (encoded, expected) = line.split_once('\t').expect("two columns");
        let bytes = if encoded == "-" {
            Vec::new()
        } else {
            decode_hex(encoded)
        };
        assert_eq!(
            go_ip_string(&bytes),
            expected,
            "row {line_number}: {}",
            encoded
        );
        rows += 1;
    }
    assert_eq!(rows, 102, "one row per scripted address");
}

#[test]
fn dynamic_blocks_trace_matches_go() {
    let text = read("blocks_trace.tsv");
    let blocks = DynamicBlocks::new();
    let mut rows = 0;
    for (line_number, line) in text.lines().enumerate() {
        if line_number == 0 {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 10, "row {line_number} has the wrong width");
        let op = fields[1];
        let domain = fields[2];
        let enabled = fields[3] == "1";
        let threshold: u32 = fields[4].parse().expect("threshold");
        let window_seconds: i64 = fields[5].parse().expect("window");
        let nxdomain_seconds: i64 = fields[6].parse().expect("nxdomain window");
        let fallback: u32 = fields[7].parse().expect("fallback");
        let now_ns: i64 = fields[8].parse().expect("now");
        let expected = fields[9];

        if op == "reset" {
            blocks.reset();
            assert_eq!(blocks.len(), 0);
            assert_eq!(expected, "-");
        } else {
            assert_eq!(op, "response", "row {line_number}: unknown op {op}");
            let response = blocks.response_for(
                domain,
                &BlockConfig {
                    enabled,
                    request_threshold: threshold,
                    window_ns: window_seconds * 1_000_000_000,
                    nx_domain_ns: nxdomain_seconds * 1_000_000_000,
                },
                fallback,
                now_ns,
            );
            assert_eq!(
                response.to_string(),
                expected,
                "row {line_number}: {domain}"
            );
        }
        rows += 1;
    }
    assert_eq!(rows, 25, "one row per scripted call");
}

fn decode_message_hex(text: &str) -> Vec<u8> {
    if text == "-" {
        return Vec::new();
    }
    decode_hex(text)
}

fn status_name(status: u8) -> &'static str {
    match status {
        diting_dns_core::message::status::ACCEPTED => "ok",
        diting_dns_core::message::status::UPSTREAM_RCODE => "rcode",
        diting_dns_core::message::status::INVALID_QUERY => "invalid_query",
        diting_dns_core::message::status::INVALID_QUERY_FLAGS => "invalid_query_flags",
        diting_dns_core::message::status::INVALID_RESPONSE => "invalid_response",
        diting_dns_core::message::status::TRANSACTION_MISMATCH => "transaction",
        diting_dns_core::message::status::QUESTION_COUNT => "question_count",
        diting_dns_core::message::status::QUESTION_MISMATCH => "question",
        other => panic!("unknown status {other}"),
    }
}

#[test]
fn message_corpus_matches_go() {
    let text = read("messages.tsv");
    let mut rows = 0;
    for (line_number, line) in text.lines().enumerate() {
        if line_number == 0 {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 13, "row {line_number} has the wrong width");
        let name = fields[0];
        let query = decode_message_hex(fields[1]);
        let response = decode_message_hex(fields[2]);

        let info = diting_dns_core::query_info(&query);
        assert_eq!(info.name, fields[3], "{name}: query name");
        assert_eq!(info.qtype.to_string(), fields[4], "{name}: query type");
        assert_eq!(
            if info.valid { "1" } else { "0" },
            fields[5],
            "{name}: query validity"
        );

        let validation = diting_dns_core::validate(&query, &response);
        assert_eq!(status_name(validation.status), fields[6], "{name}: status");
        assert_eq!(
            validation.rcode.to_string(),
            fields[7],
            "{name}: validation rcode"
        );

        let extracted = diting_dns_core::extract(&response);
        if fields[8] == "-" {
            assert!(extracted.is_none(), "{name}: expected an unparsable answer");
            rows += 1;
            continue;
        }
        let extracted = extracted.unwrap_or_else(|| panic!("{name}: expected a parsable answer"));
        assert_eq!(
            if extracted.blocked { "1" } else { "0" },
            fields[8],
            "{name}: blocked"
        );
        assert_eq!(extracted.resolved_ips, fields[9], "{name}: resolved");
        let chain = extracted
            .chain_targets
            .iter()
            .map(|target| format!("{}:{}", target.kind.as_str(), target.domain))
            .collect::<Vec<_>>()
            .join("|");
        assert_eq!(
            if chain.is_empty() {
                "-"
            } else {
                chain.as_str()
            },
            fields[10],
            "{name}: chain"
        );
        let records = extracted
            .addresses
            .iter()
            .map(|record| {
                let kind = if record.rrtype == 1 { "A" } else { "AAAA" };
                format!("{kind}:{}:{}", encode_hex(&record.address), record.ttl)
            })
            .collect::<Vec<_>>()
            .join("|");
        assert_eq!(
            if records.is_empty() {
                "-"
            } else {
                records.as_str()
            },
            fields[11],
            "{name}: records"
        );
        let question = if extracted.question_name.is_empty() {
            "-".to_string()
        } else {
            extracted.question_name.clone()
        };
        assert_eq!(question, fields[12], "{name}: question");
        rows += 1;
    }
    assert_eq!(rows, 32, "one row per scripted message");
}

fn encode_hex(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(DIGITS[(byte >> 4) as usize] as char);
        out.push(DIGITS[(byte & 0x0f) as usize] as char);
    }
    out
}
